from pathlib import Path
import json,re
event="1791201148-f79e6fb36b9e"
base=Path.home()/".local/share/prediction-chat-bridge"
msg=None
for d in ("sent","inflight","outbox"):
    p=base/d/f"{event}.json"
    if p.is_file():
        obj=json.loads(p.read_text(encoding="utf-8",errors="replace"))
        msg=str(obj.get("message") or "")
        break
if msg is None:
    print("SEMANTIC_VIS=EVENT_MISSING",flush=True)
    raise SystemExit(42)

payload=None
for line in msg.splitlines():
    k=line.find("PRODUCTION_DIFF_INSPECT ")
    if k>=0:
        raw=line[k+len("PRODUCTION_DIFF_INSPECT "):].strip()
        try:
            payload=json.loads(raw)
        except Exception:
            pass
if not isinstance(payload,dict):
    print("SEMANTIC_VIS=DIFF_PAYLOAD_MISSING",flush=True)
    raise SystemExit(42)

body=str(payload.get("diff") or "")
sections=re.split(r'(?=^diff --git a/)',body,flags=re.M)
out=[]
root=Path.cwd()
for sec in sections:
    m=re.match(r'^diff --git a/(.+?) b/(.+?)$',sec,re.M)
    if not m:
        continue
    rel=m.group(2)
    canon=root/rel
    try:
        canon_lines=set(canon.read_text(encoding="utf-8",errors="replace").splitlines())
    except OSError:
        canon_lines=set()
    adds=[]
    rems=[]
    for ln in sec.splitlines():
        if ln.startswith("+++") or ln.startswith("---"):
            continue
        if ln.startswith("+"):
            x=ln[1:]
            if x.strip():
                adds.append(x)
        elif ln.startswith("-"):
            x=ln[1:]
            if x.strip():
                rems.append(x)
    add_missing=sorted(set(x for x in adds if x not in canon_lines))
    rem_still=sorted(set(x for x in rems if x in canon_lines))
    strong=(not add_missing and not rem_still)
    out.append({
      "file":rel.rsplit("/",1)[-1],
      "strong":strong,
      "add_missing_n":len(add_missing),
      "rem_still_n":len(rem_still),
      "add_missing_sample":add_missing[:2],
      "rem_still_sample":rem_still[:2],
    })
print("SEMANTIC_VIS="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(42)
